mapper.select:
SELECT COUNT( 1 ) AS allCount, SUM( CASE WHEN goods_appraise.goods_score >= 4 THEN 1 ELSE 0 END ) AS goodCount, SUM( CASE WHEN goods_appraise.goods_score = 3 THEN 1 ELSE 0 END ) AS badCount, SUM( CASE WHEN 2 >=goods_appraise.goods_score THEN 1 ELSE 0 END ) AS negativeCount, SUM( CASE WHEN goods_appraise.pic_urls IS NOT NULL AND goods_appraise.pic_urls != '' THEN 1 ELSE 0 END ) AS imageCount FROM goods_appraise AS goods_appraise
AND goods_appraise.del_flag='0' AND goods_appraise.appraise_type = 0
AND goods_appraise.`spu_id` = #{query.spuId}
AND goods_appraise.`user_id` = #{query.userId}

SELECT goods_spu.`name` AS spuName, goods_spu.spu_urls, goods_appraise.id, goods_appraise.spu_id, goods_appraise.order_id, goods_appraise.order_item_id, goods_appraise.user_id, goods_appraise.avatar_url, goods_appraise.nickname, goods_appraise.create_time, goods_appraise.del_flag, goods_appraise.update_time, goods_appraise.pic_urls, goods_appraise.goods_score, goods_appraise.logistics_score, goods_appraise.service_score, goods_appraise.business_reply, goods_appraise.reply_time, goods_appraise.content, goods_appraise.appraise_type, goods_appraise.is_anonymous, goods_appraise.tags, goods_appraise.advance_content, goods_appraise.advance_pic_urls, goods_appraise.advance_time, goods_appraise.modify_time, goods_appraise.tenant_id, goods_appraise.create_by, goods_appraise.update_by FROM goods_appraise AS goods_appraise LEFT JOIN goods_spu AS goods_spu ON goods_spu.id = goods_appraise.spu_id
AND goods_appraise.del_flag = '0'
AND goods_appraise.nickname = #{query.nickname}
AND goods_appraise.user_id = #{query.userId}
AND goods_appraise.order_id = #{query.orderId}
AND goods_appraise.spu_id = #{query.spuId}
AND goods_appraise.appraise_type = #{query.appraiseType}
ORDER BY goods_appraise.create_time DESC, goods_appraise.id DESC

SELECT avatar_url FROM goods_appraise AS goods_appraise
AND goods_appraise.del_flag = '0' AND goods_appraise.appraise_type = 0 AND IFNULL(goods_appraise.is_anonymous, 0) != 1 AND goods_appraise.avatar_url IS NOT NULL AND goods_appraise.avatar_url != ''
AND goods_appraise.spu_id = #{spuId}
GROUP BY goods_appraise.avatar_url ORDER BY MAX(goods_appraise.create_time) DESC LIMIT #{limit}
